import math
import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   bool training,
                                   double momentum,
                                   double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <algorithm>
#include <cstdint>
using namespace cute;
// ---------------------------------------------------------------------
// Device helper: finalize per-channel batch statistics (training mode),
// update running stats, and fold affine parameters into scale/shift.
// Called by the last block that finishes reducing a given channel, so
// that no separate finalize kernel launch (and its associated launch
// overhead + tiny/underutilized grid) is required.
// ---------------------------------------------------------------------
__device__ __forceinline__ void bn_do_finalize_train(
    int c, double s, double q, int64_t count,
    float eps, float momentum,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    float* __restrict__ scale_out,
    float* __restrict__ shift_out)
{
  double m   = s / (double)count;
  double var = q / (double)count - m * m;
  if (var < 0.0) var = 0.0;
  float mean_f   = (float)m;
  float invstd_f = (float)(1.0 / sqrt(var + (double)eps));
  double unbiased_var = (count > 1) ? var * (double)count / (double)(count - 1) : var;
  running_mean[c] = (float)((1.0 - (double)momentum) * (double)running_mean[c] + (double)momentum * m);
  running_var[c]  = (float)((1.0 - (double)momentum) * (double)running_var[c]  + (double)momentum * unbiased_var);
  float sc = invstd_f * weight[c];
  scale_out[c] = sc;
  shift_out[c] = bias[c] - mean_f * sc;
}
// ---------------------------------------------------------------------
// Kernel 1: per-channel reduction (sum, sum of squares) over N,H,W.
// The last block to finish accumulating a given channel (tracked via a
// global atomic counter) directly performs the training-mode finalize
// step (mean/var, running-stat update, scale/shift folding), fusing what
// used to be a separate kernel launch into this one. This removes a
// kernel launch that previously ran with a tiny, severely underutilized
// grid (a single block for C <= 128 channels).
// ---------------------------------------------------------------------
__launch_bounds__(256, 8)
__global__ void bn_reduce_kernel(const float* __restrict__ X,
                                  int N, int C, int H, int W,
                                  double* __restrict__ sum,
                                  double* __restrict__ sumsq,
                                  int* __restrict__ counters,
                                  int64_t count,
                                  float eps, float momentum,
                                  const float* __restrict__ weight,
                                  const float* __restrict__ bias,
                                  float* __restrict__ running_mean,
                                  float* __restrict__ running_var,
                                  float* __restrict__ scale_out,
                                  float* __restrict__ shift_out)
{
  int c = blockIdx.x;
  int HW = H * W;
  int64_t strideN = (int64_t)C * HW;
  // View of channel c: shape (N, HW), stride (C*H*W, 1)
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)c * HW),
                         make_shape(N, HW),
                         make_stride(strideN, Int<1>{}));
  int64_t total  = (int64_t)N * HW;
  int64_t tid    = (int64_t)blockIdx.y * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)gridDim.y * blockDim.x;
  double local_sum   = 0.0;
  double local_sumsq = 0.0;
  for (int64_t idx = tid; idx < total; idx += stride) {
    int n  = (int)(idx / HW);
    int hw = (int)(idx % HW);
    float v = mX(n, hw);
    local_sum   += (double)v;
    local_sumsq += (double)v * (double)v;
  }
  unsigned mask = 0xffffffff;
  for (int offset = 16; offset > 0; offset >>= 1) {
    local_sum   += __shfl_down_sync(mask, local_sum, offset);
    local_sumsq += __shfl_down_sync(mask, local_sumsq, offset);
  }
  __shared__ double s_sum[32];
  __shared__ double s_sumsq[32];
  int warpId = threadIdx.x >> 5;
  int lane   = threadIdx.x & 31;
  if (lane == 0) {
    s_sum[warpId]   = local_sum;
    s_sumsq[warpId] = local_sumsq;
  }
  __syncthreads();
  int nwarps = blockDim.x >> 5;
  if (warpId == 0) {
    double sv = (lane < nwarps) ? s_sum[lane]   : 0.0;
    double qv = (lane < nwarps) ? s_sumsq[lane] : 0.0;
    for (int offset = 16; offset > 0; offset >>= 1) {
      sv += __shfl_down_sync(mask, sv, offset);
      qv += __shfl_down_sync(mask, qv, offset);
    }
    if (lane == 0) {
      atomicAdd(&sum[c], sv);
      atomicAdd(&sumsq[c], qv);
      __threadfence();
      int cnt = atomicAdd(&counters[c], 1) + 1;
      if (cnt == gridDim.y) {
        bn_do_finalize_train(c, sum[c], sumsq[c], count, eps, momentum,
                              weight, bias, running_mean, running_var,
                              scale_out, shift_out);
      }
    }
  }
}
// ---------------------------------------------------------------------
// Kernel 1b: vectorized (float4) per-channel reduction, used when HW is
// divisible by 4 and the tensor is 16-byte aligned. Also fuses the
// training-mode finalize step, as above.
// ---------------------------------------------------------------------
__launch_bounds__(256, 8)
__global__ void bn_reduce_kernel_vec4(const float4* __restrict__ X,
                                       int64_t strideN4, int64_t HW4,
                                       int N,
                                       double* __restrict__ sum,
                                       double* __restrict__ sumsq,
                                       int* __restrict__ counters,
                                       int64_t count,
                                       float eps, float momentum,
                                       const float* __restrict__ weight,
                                       const float* __restrict__ bias,
                                       float* __restrict__ running_mean,
                                       float* __restrict__ running_var,
                                       float* __restrict__ scale_out,
                                       float* __restrict__ shift_out)
{
  int c = blockIdx.x;
  int64_t total  = (int64_t)N * HW4;
  int64_t tid    = (int64_t)blockIdx.y * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)gridDim.y * blockDim.x;
  const float4* base = X + (int64_t)c * HW4;
  double local_sum   = 0.0;
  double local_sumsq = 0.0;
  for (int64_t idx = tid; idx < total; idx += stride) {
    int64_t n   = idx / HW4;
    int64_t hw4 = idx % HW4;
    float4 v = base[n * strideN4 + hw4];
    local_sum   += (double)v.x + (double)v.y + (double)v.z + (double)v.w;
    local_sumsq += (double)v.x * (double)v.x + (double)v.y * (double)v.y +
                   (double)v.z * (double)v.z + (double)v.w * (double)v.w;
  }
  unsigned mask = 0xffffffff;
  for (int offset = 16; offset > 0; offset >>= 1) {
    local_sum   += __shfl_down_sync(mask, local_sum, offset);
    local_sumsq += __shfl_down_sync(mask, local_sumsq, offset);
  }
  __shared__ double s_sum[32];
  __shared__ double s_sumsq[32];
  int warpId = threadIdx.x >> 5;
  int lane   = threadIdx.x & 31;
  if (lane == 0) {
    s_sum[warpId]   = local_sum;
    s_sumsq[warpId] = local_sumsq;
  }
  __syncthreads();
  int nwarps = blockDim.x >> 5;
  if (warpId == 0) {
    double sv = (lane < nwarps) ? s_sum[lane]   : 0.0;
    double qv = (lane < nwarps) ? s_sumsq[lane] : 0.0;
    for (int offset = 16; offset > 0; offset >>= 1) {
      sv += __shfl_down_sync(mask, sv, offset);
      qv += __shfl_down_sync(mask, qv, offset);
    }
    if (lane == 0) {
      atomicAdd(&sum[c], sv);
      atomicAdd(&sumsq[c], qv);
      __threadfence();
      int cnt = atomicAdd(&counters[c], 1) + 1;
      if (cnt == gridDim.y) {
        bn_do_finalize_train(c, sum[c], sumsq[c], count, eps, momentum,
                              weight, bias, running_mean, running_var,
                              scale_out, shift_out);
      }
    }
  }
}
// ---------------------------------------------------------------------
// Kernel 2b: finalize statistics for eval mode (use running stats) and
// directly fold per-channel affine parameters into scale/shift, fused
// into a single kernel for the same reason as above.
// ---------------------------------------------------------------------
__global__ void bn_finalize_eval_kernel(const float* __restrict__ running_mean,
                                         const float* __restrict__ running_var,
                                         int C, float eps,
                                         const float* __restrict__ weight,
                                         const float* __restrict__ bias,
                                         float* __restrict__ scale_out,
                                         float* __restrict__ shift_out)
{
  int c = blockIdx.x * blockDim.x + threadIdx.x;
  if (c >= C) return;
  float mean_f   = running_mean[c];
  float invstd_f = 1.0f / sqrtf(running_var[c] + eps);
  float s = invstd_f * weight[c];
  scale_out[c] = s;
  shift_out[c] = bias[c] - mean_f * s;
}
// ---------------------------------------------------------------------
// Kernel 3: normalize + affine transform (elementwise)
// ---------------------------------------------------------------------
__launch_bounds__(256, 8)
__global__ void bn_normalize_kernel(const float* __restrict__ X,
                                     float* __restrict__ Y,
                                     const float* __restrict__ scale,
                                     const float* __restrict__ shift,
                                     int N, int C, int H, int W)
{
  int64_t HW = (int64_t)H * W;
  int64_t NC = (int64_t)N * C;
  int64_t total = NC * HW;
  // Flatten (N,C) outer dims: contiguous with stride HW between them.
  auto mX = make_tensor(make_gmem_ptr(X), make_shape(NC, HW), make_stride(HW, Int<1>{}));
  auto mY = make_tensor(make_gmem_ptr(Y), make_shape(NC, HW), make_stride(HW, Int<1>{}));
  int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)gridDim.x * blockDim.x;
  for (; idx < total; idx += stride) {
    int64_t nc = idx / HW;
    int64_t hw = idx % HW;
    int c = (int)(nc % C);
    float v = mX(nc, hw);
    float y = v * scale[c] + shift[c];
    mY(nc, hw) = y;
  }
}
// ---------------------------------------------------------------------
// Kernel 3b: normalize + affine transform (vectorized float4 elementwise)
// Valid when HW is divisible by 4 (contiguous NCHW layout guarantees
// that 4 consecutive elements along the last dim belong to the same
// (n, c) slice, so per-channel mean/invstd/weight/bias apply uniformly).
// ---------------------------------------------------------------------
__launch_bounds__(256, 8)
__global__ void bn_normalize_kernel_vec4(const float4* __restrict__ X,
                                          float4* __restrict__ Y,
                                          const float* __restrict__ scale,
                                          const float* __restrict__ shift,
                                          int64_t NC, int64_t HW4, int C)
{
  // Grid mapping: blockIdx.y (with grid-stride) walks over the (n,c)
  // slices so the expensive division/modulo to recover the channel index
  // is computed once per slice instead of once per element. blockIdx.x
  // (with grid-stride) walks contiguously within a slice, preserving
  // coalesced float4 accesses. Within a slice, loads/stores are unrolled
  // by a factor of 4 to increase memory-level parallelism (more
  // outstanding transactions in flight), better hiding global memory
  // latency for this memory-bound kernel.
  int64_t nc_start  = blockIdx.y;
  int64_t nc_stride = gridDim.y;
  int64_t hw_start  = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t hw_stride = (int64_t)gridDim.x * blockDim.x;
  const int UNROLL = 4;
  int64_t hw_stride_u = hw_stride * UNROLL;
  for (int64_t nc = nc_start; nc < NC; nc += nc_stride) {
    int c = (int)(nc % C);
    float s = scale[c];
    float b = shift[c];
    const float4* __restrict__ xrow = X + nc * HW4;
    float4* __restrict__ yrow = Y + nc * HW4;
    int64_t hw = hw_start;
    int64_t bound = HW4 - (int64_t)(UNROLL - 1) * hw_stride;
    for (; hw < bound; hw += hw_stride_u) {
      float4 v0 = xrow[hw];
      float4 v1 = xrow[hw + hw_stride];
      float4 v2 = xrow[hw + 2 * hw_stride];
      float4 v3 = xrow[hw + 3 * hw_stride];
      float4 o0, o1, o2, o3;
      o0.x = v0.x * s + b; o0.y = v0.y * s + b; o0.z = v0.z * s + b; o0.w = v0.w * s + b;
      o1.x = v1.x * s + b; o1.y = v1.y * s + b; o1.z = v1.z * s + b; o1.w = v1.w * s + b;
      o2.x = v2.x * s + b; o2.y = v2.y * s + b; o2.z = v2.z * s + b; o2.w = v2.w * s + b;
      o3.x = v3.x * s + b; o3.y = v3.y * s + b; o3.z = v3.z * s + b; o3.w = v3.w * s + b;
      yrow[hw]                 = o0;
      yrow[hw + hw_stride]     = o1;
      yrow[hw + 2 * hw_stride] = o2;
      yrow[hw + 3 * hw_stride] = o3;
    }
    for (; hw < HW4; hw += hw_stride) {
      float4 v = xrow[hw];
      float4 out;
      out.x = v.x * s + b;
      out.y = v.y * s + b;
      out.z = v.z * s + b;
      out.w = v.w * s + b;
      yrow[hw] = out;
    }
  }
}
// ---------------------------------------------------------------------
// Host wrapper
// ---------------------------------------------------------------------
torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   bool training,
                                   double momentum,
                                   double eps)
{
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.dim() == 4, "x must be NCHW");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA");
  TORCH_CHECK(running_mean.is_cuda() && running_var.is_cuda(), "running stats must be CUDA");
  auto x_c = x.contiguous();
  int N = (int)x_c.size(0);
  int C = (int)x_c.size(1);
  int H = (int)x_c.size(2);
  int W = (int)x_c.size(3);
  auto y = torch::empty_like(x_c);
  auto opts_f = x.options();
  auto opts_d = x.options().dtype(at::kDouble);
  auto opts_i = x.options().dtype(at::kInt);
  auto scale_buf   = torch::empty({C}, opts_f);
  auto shift_buf   = torch::empty({C}, opts_f);
  auto weight_c = weight.contiguous();
  auto bias_c   = bias.contiguous();
  auto running_mean_c = running_mean.contiguous();
  auto running_var_c  = running_var.contiguous();
  bool rm_same = running_mean_c.data_ptr() == running_mean.data_ptr();
  bool rv_same = running_var_c.data_ptr() == running_var.data_ptr();
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  int64_t HW = (int64_t)H * W;
  bool hw_div4 = (HW % 4 == 0);
  bool x_aligned = (reinterpret_cast<uintptr_t>(x_c.data_ptr<float>()) % 16 == 0);
  bool y_aligned = (reinterpret_cast<uintptr_t>(y.data_ptr<float>()) % 16 == 0);
  bool can_vectorize_reduce = hw_div4 && x_aligned;
  bool can_vectorize = can_vectorize_reduce && y_aligned;
  if (training) {
    auto sum_buf   = torch::zeros({C}, opts_d);
    auto sumsq_buf = torch::zeros({C}, opts_d);
    auto counters  = torch::zeros({C}, opts_i);
    int64_t total_per_c = (int64_t)N * HW;
    int block = 256;
    int64_t bpc64 = std::min<int64_t>(64, (total_per_c + block - 1) / block);
    int blocksPerChannel = (int)std::max<int64_t>(1, bpc64);
    dim3 grid((unsigned)C, (unsigned)blocksPerChannel);
    int64_t count = (int64_t)N * H * W;
    if (can_vectorize_reduce) {
      int64_t HW4 = HW / 4;
      int64_t strideN4 = (int64_t)C * HW4;
      bn_reduce_kernel_vec4<<<grid, block, 0, stream>>>(
          reinterpret_cast<const float4*>(x_c.data_ptr<float>()),
          strideN4, HW4, N,
          sum_buf.data_ptr<double>(), sumsq_buf.data_ptr<double>(),
          counters.data_ptr<int>(), count,
          (float)eps, (float)momentum,
          weight_c.data_ptr<float>(), bias_c.data_ptr<float>(),
          running_mean_c.data_ptr<float>(), running_var_c.data_ptr<float>(),
          scale_buf.data_ptr<float>(), shift_buf.data_ptr<float>());
    } else {
      bn_reduce_kernel<<<grid, block, 0, stream>>>(
          x_c.data_ptr<float>(), N, C, H, W,
          sum_buf.data_ptr<double>(), sumsq_buf.data_ptr<double>(),
          counters.data_ptr<int>(), count,
          (float)eps, (float)momentum,
          weight_c.data_ptr<float>(), bias_c.data_ptr<float>(),
          running_mean_c.data_ptr<float>(), running_var_c.data_ptr<float>(),
          scale_buf.data_ptr<float>(), shift_buf.data_ptr<float>());
    }
  } else {
    int fb = 128;
    int fg = (C + fb - 1) / fb;
    bn_finalize_eval_kernel<<<fg, fb, 0, stream>>>(
        running_mean_c.data_ptr<float>(), running_var_c.data_ptr<float>(), C, (float)eps,
        weight_c.data_ptr<float>(), bias_c.data_ptr<float>(),
        scale_buf.data_ptr<float>(), shift_buf.data_ptr<float>());
  }
  if (can_vectorize) {
    int64_t NC  = (int64_t)N * C;
    int64_t HW4 = HW / 4;
    int nblock = 256;
    int64_t gridx64 = (HW4 + nblock - 1) / nblock;
    gridx64 = std::min<int64_t>(gridx64, 65535LL);
    int gridx = (int)std::max<int64_t>(1, gridx64);
    int64_t gridy64 = std::min<int64_t>(NC, 65535LL);
    int gridy = (int)std::max<int64_t>(1, gridy64);
    dim3 grid_norm((unsigned)gridx, (unsigned)gridy);
    bn_normalize_kernel_vec4<<<grid_norm, nblock, 0, stream>>>(
        reinterpret_cast<const float4*>(x_c.data_ptr<float>()),
        reinterpret_cast<float4*>(y.data_ptr<float>()),
        scale_buf.data_ptr<float>(), shift_buf.data_ptr<float>(),
        NC, HW4, C);
  } else {
    int64_t total = (int64_t)N * C * HW;
    int nblock = 256;
    int64_t ngrid64 = (total + nblock - 1) / nblock;
    ngrid64 = std::min<int64_t>(ngrid64, 65535LL);
    int ngrid = (int)std::max<int64_t>(1, ngrid64);
    bn_normalize_kernel<<<ngrid, nblock, 0, stream>>>(
        x_c.data_ptr<float>(), y.data_ptr<float>(),
        scale_buf.data_ptr<float>(), shift_buf.data_ptr<float>(),
        N, C, H, W);
  }
  if (!rm_same) running_mean.copy_(running_mean_c);
  if (!rv_same) running_var.copy_(running_var_c);
  return y;
}
"""
import glob
def _find_cutlass_include():
    candidates = [
        os.environ.get("CUTLASS_HOME", "") and os.path.join(os.environ["CUTLASS_HOME"], "include"),
        os.environ.get("CUTLASS_PATH", "") and os.path.join(os.environ["CUTLASS_PATH"], "include"),
        os.path.expanduser("~/cutlass/include"),
    ]
    try:
        import cutlass as _cutlass_pkg
        candidates.append(os.path.join(os.path.dirname(_cutlass_pkg.__file__), "include"))
    except ImportError:
        pass
    try:
        import site
        site_dirs = []
        try:
            site_dirs.extend(site.getsitepackages())
        except Exception:
            pass
        try:
            site_dirs.append(site.getusersitepackages())
        except Exception:
            pass
        for site_packages in site_dirs:
            candidates.append(os.path.join(site_packages, "cutlass", "include"))
    except Exception:
        pass
    for site_packages in glob.glob(os.path.join(os.path.dirname(os.__file__), "site-packages")):
        candidates.append(os.path.join(site_packages, "cutlass", "include"))
    for c in candidates:
        if c and os.path.exists(os.path.join(c, "cute", "tensor.hpp")):
            return c
    # Last resort: fetch a CUTLASS checkout containing the CuTe headers.
    cache_dir = os.environ.get("CUTLASS_CACHE_DIR", os.path.expanduser("~/.cache/cutlass_cute"))
    inc = os.path.join(cache_dir, "include")
    if not os.path.exists(os.path.join(inc, "cute", "tensor.hpp")):
        try:
            import subprocess
            parent = os.path.dirname(cache_dir)
            if parent:
                os.makedirs(parent, exist_ok=True)
            if not os.path.exists(cache_dir):
                subprocess.check_call([
                    "git", "clone", "--depth", "1",
                    "https://github.com/NVIDIA/cutlass.git", cache_dir
                ])
        except Exception:
            pass
    if os.path.exists(os.path.join(inc, "cute", "tensor.hpp")):
        return inc
    raise RuntimeError(
        "cute/tensor.hpp not found. Set the CUTLASS_HOME (or CUTLASS_PATH) "
        "environment variable to the root of a CUTLASS checkout that "
        "contains 'include/cute/tensor.hpp'."
    )
cutlass_include = _find_cutlass_include()
bn_ext = load_inline(
    name="cute_batchnorm2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["batchnorm2d_forward"],
    extra_cflags=["-O3", "-std=c++17"],
    extra_cuda_cflags=["-O3", "--expt-relaxed-constexpr", "-std=c++17"],
    extra_include_paths=[cutlass_include],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self, num_features: int, eps: float = 1e-5, momentum: float = 0.1):
        super().__init__()
        self.num_features = num_features
        self.eps = eps
        self.momentum = momentum
        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))
        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))
        self._ext = bn_ext
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.training:
            self.num_batches_tracked += 1
        return self._ext.batchnorm2d_forward(
            x.contiguous(),
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            self.training,
            float(self.momentum),
            float(self.eps),
        )

