import math
import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   bool training,
