// (n, c) slice, so per-channel mean/invstd/weight/bias apply uniformly).
// ---------------------------------------------------------------------
__launch_bounds__(256, 8)
__global__ void bn_normalize_kernel_vec4(const float4* __restrict__ X,
                                          float4* __restrict__ Y,
                                          const float* __restrict__ scale,
                                          const float* __restrict__ shift,
                                          int64_t NC, int64_t HW4, int C)
{
