  // slices so the expensive division/modulo to recover the channel index
  // is computed once per slice instead of once per element. blockIdx.x
  // (with grid-stride) walks contiguously within a slice, preserving
  // coalesced float4 accesses.
  int64_t nc_start  = blockIdx.y;
  int64_t nc_stride = gridDim.y;
  int64_t hw_start  = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t hw_stride = (int64_t)gridDim.x * blockDim.x;
