          sum_buf.data_ptr<double>(), sumsq_buf.data_ptr<double>(),
          counters.data_ptr<int>(), count,
          (float)eps, (float)momentum,
          weight_c.data_ptr<float>(), bias_c.data_ptr<float>(),
          running_mean_c.data_ptr<float>(), running_var_c.data_ptr<float>(),
